/* Auth block layout. Visuals come from AuthLayout, AuthCard and the tokens. */

.frame {
  width: 100%;
  height: 100%;
}

.mark {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  letter-spacing: var(--tracking-display);
  color: inherit;
}

.glyph {
  display: inline-grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-sm);
  background: var(--brand-gradient);
  box-shadow: var(--glow-sm);
  font-size: 14px;
  color: var(--ink-inverse);
}

.help {
  font-size: var(--text-small);
  font-weight: 700;
  color: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.otp {
  display: flex;
  justify-content: center;
}

.alt {
  font-size: var(--text-small);
  color: var(--ink-muted);
  text-align: center;
}

.link {
  padding: 0;
  border: 0;
  background: none;
  font-weight: 700;
  color: var(--ink-brand);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.link:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
  border-radius: var(--r-2xs);
}

.setup {
  display: grid;
  grid-template-columns: 148px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

@media (max-width: 480px) {
  .setup {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
  }
}

.qr {
  display: block;
  width: 148px;
  height: 148px;
  border-radius: var(--r-md);
  box-shadow: inset 0 0 0 1px var(--line);
}

.steps {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: var(--text-small);
  color: var(--ink-body);
}

.secret {
  align-self: flex-start;
  padding: 6px 10px;
  border-radius: var(--r-sm);
  background: var(--surface-sunken);
  box-shadow: inset 0 0 0 1px var(--line);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  color: var(--ink-heading);
}

.row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

@media (max-width: 480px) {
  .row {
    grid-template-columns: minmax(0, 1fr);
  }
}

.between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

"use client";

import { useState } from "react";
import { AuthCard, AuthLayout } from "@/components/shell/AuthCard";
import { Button } from "@/components/ui/Button/Button";
import { IconMail, IconShield } from "@/components/ui/Icon/Icon";
import styles from "./Auth.module.css";

export type AuthCheckEmailProps = {
  /** Fill the parent instead of the viewport. */
  contained?: boolean;
};

/** After a magic link or reset: "check your email", with resend. Drop it at app/check-email. */
export default function AuthCheckEmail({ contained }: AuthCheckEmailProps) {
  const [sent, setSent] = useState(false);
  return (
    <div className={contained ? styles.frame : undefined}>
      <AuthLayout
        contained={contained}
        header={
          <span className={styles.mark}>
            <span className={styles.glyph} aria-hidden="true">
              A
            </span>
            Acme
          </span>
        }
        footer={
          <>
            <IconShield size={14} />
            Acme never asks for your password or code by email.
          </>
        }
      >
        <AuthCard icon={<IconMail size={22} />} title="Check your email" subtitle="We sent a sign-in link to jane@acme.example. It works once and expires in 15 minutes." back={{ href: "#login", label: "Back to sign in" }}>
          <Button size="lg" fullWidth variant="secondary" href="mailto:">
            Open your email
          </Button>
          <p className={styles.alt} role="status">
            {sent ? (
              "Sent again. Check your spam folder too."
            ) : (
              <>
                Nothing yet?{" "}
                <button type="button" className={styles.link} onClick={() => setSent(true)}>
                  Send it again
                </button>
              </>
            )}
          </p>
        </AuthCard>
      </AuthLayout>
    </div>
  );
}

import AuthCheckEmail from "@/components/blocks/auth-check-email";

export default function Page() {
  return <AuthCheckEmail />;
}
